describe('Product Sorting by Price', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should sort products by price in ascending order when selecting "lohi"', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify login successful and products are visible
    cy.get('[data-testid="inventory-item"]').should('be.visible');

    // Get initial prices to verify sorting later
    cy.get('[data-testid="inventory-item"]').then(($items) => {
      const initialPrices = $items.map((item, index) => {
        return parseFloat(item.find('[data-testid="inventory_item_price"]').text());
      }).get();
      expect(initialPrices).to.have.length(6);
    });

    // Select "lohi" (lowest price first) from sort dropdown
    cy.get('[data-testid="product-sort-container"]').select('lohi');

    // Verify products are reordered by price in ascending order
    cy.get('[data-testid="inventory-item"]').then(($items) => {
      const sortedPrices = $items.map((item, index) => {
        return parseFloat(item.find('[data-testid="inventory_item_price"]').text());
      }).get();

      // Check if prices are in ascending order
      for (let i = 0; i < sortedPrices.length - 1; i++) {
        expect(sortedPrices[i]).to.be.lte(sortedPrices[i + 1]);
      }
    });

    // Verify the first item is the cheapest
    cy.get('[data-testid="inventory-item:first-child [data-testid="inventory_item_price"]').should('contain', '$1.99');
  });

  it('should not sort when sort dropdown is not selected', () => {
    // Login with standard user
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify products are visible
    cy.get('[data-testid="inventory-item"]').should('be.visible');

    // Verify default sort order is maintained (or no change occurs)
    cy.get('[data-testid="inventory-item"]').then(($items) => {
      const initialPrices = $items.map((item, index) => {
        return parseFloat(item.find('[data-testid="inventory_item_price"]').text());
      }).get();

      // Verify the first item is not necessarily the cheapest if default sort is not price
      expect(initialPrices[0]).to.be.greaterThan(0);
    });

    // Verify the sort dropdown has a default value and is not empty
    cy.get('[data-testid="product-sort-container"]').should('have.value', 'default');

    // Verify the sort button is not disabled
    cy.get('[data-testid="sort-button"]').should('not.be.disabled');
  });
});
